import * as G from './workshop.js';
import {Workshop} from './scene.js';
const $=s=>document.querySelector(s);
let state=G.newWorkshop(),scene,active=false,action=null,keys=new Set(),last=performance.now(),elapsed=0,saveClock=0,hudClock=0,toastTimer,sound=true,ctx,lockedOnce=false;
try{const raw=localStorage.getItem(G.SAVE_KEY),v5=localStorage.getItem('ember-edge-workshop-v5'),v4=localStorage.getItem('ember-edge-workshop-v4'),v3=localStorage.getItem('ember-edge-workshop-v3'),v2=localStorage.getItem('ember-edge-first-person-v2');if(raw)state=G.restoreWorkshop(raw);else if(v5)state=G.migrateV5(JSON.parse(v5));else if(v4)state=G.migrateV4(JSON.parse(v4));else if(v3)state=G.migrateV3(JSON.parse(v3));else if(v2)state=G.migrateV2(JSON.parse(v2));}catch{$('#save-status').textContent='旧存档保留，本次开启新工房';}
try{scene=new Workshop($('#world'),state);}catch(e){console.error(e);$('#world').innerHTML='<div class="fallback">3D 工房未能启动。请启用硬件加速，或使用支持 WebGL 的桌面浏览器。</div>';$('#enter').disabled=true;$('#enter').textContent='需要支持 WebGL 的浏览器';}
const canvas=scene?.renderer.domElement;
function toast(msg){if(!msg)return;$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4600);}
function save(){try{localStorage.setItem(G.SAVE_KEY,JSON.stringify(state));$('#save-status').textContent='进度已保存';}catch{$('#save-status').textContent='浏览器存储不可用';}}
function tone(type){if(!sound)return;try{ctx??=new (window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),v=ctx.createGain(),t=ctx.currentTime;o.connect(v);v.connect(ctx.destination);o.type=type==='hit'||type==='break'?'triangle':'sine';o.frequency.setValueAtTime(type==='hit'?780:type==='break'?110:type==='sell'?520:290,t);o.frequency.exponentialRampToValueAtTime(type==='hit'?180:type==='break'?35:type==='sell'?1050:440,t+.18);v.gain.setValueAtTime(.065,t);v.gain.exponentialRampToValueAtTime(.001,t+.3);o.start(t);o.stop(t+.32);}catch{}}
function perform(fn){try{const result=fn();scene.sync(state);save();renderHUD();toast(typeof result==='string'?result:result?.message);checkFailure();return result;}catch(e){toast(e.message);return null;}}
function cancel(){if(action?.type!=='transition')action=null;keys.clear();}
function pause(){if(!active)return;active=false;cancel();save();document.body.classList.add('paused');$('#sleep-screen').hidden=true;if(!state.gameOver){$('#menu').hidden=false;$('#enter').innerHTML='继续锻造 <span>→</span>';}if(document.pointerLockElement)document.exitPointerLock();}
async function enter(){if(!scene||state.gameOver)return;$('#menu').hidden=true;document.body.classList.remove('paused');active=true;last=performance.now();if(action?.type==='transition')$('#sleep-screen').hidden=false;try{await canvas.requestPointerLock();}catch{toast('在画面内移动鼠标或使用方向键环顾，ESC 暂停。');}canvas.focus();}
function checkFailure(){if(!state.gameOver)return;active=false;action=null;keys.clear();$('#sleep-screen').hidden=true;$('#menu').hidden=true;$('#game-over').hidden=false;$('#failure-reason').textContent=state.gameOver.reason;$('#failure-stats').textContent=`经营至第 ${state.day} 天 · 售出 ${state.sold} 把剑 · 获得 ${state.tokens} 枚炉印`;document.body.classList.add('paused');if(document.pointerLockElement)document.exitPointerLock();save();}
$('#restart').addEventListener('click',()=>{state=G.newWorkshop();action=null;elapsed=0;scene.sync(state);$('#game-over').hidden=true;save();renderHUD();enter();});
$('#enter').addEventListener('click',enter);document.body.classList.add('paused');if(matchMedia('(pointer:coarse)').matches)$('#menu-note').textContent='请连接键盘与鼠标游玩。';
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===canvas)lockedOnce=true;else if(active&&lockedOnce)pause();});window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('pagehide',save);
function changeSlot(fn){if(!active||action?.type==='transition')return;if(action){action=null;scene.sync(state);}perform(fn);}
window.addEventListener('keydown',e=>{if(['KeyW','KeyA','KeyS','KeyD','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'){pause();return;}if(!active)return;keys.add(e.code);if(e.repeat)return;if(/^Digit[1-5]$/.test(e.code))changeSlot(()=>G.selectSlot(state,Number(e.code.at(-1))-1));if(e.code==='KeyH')$('#guide').hidden=!$('#guide').hidden;if(e.code==='KeyM'){sound=!sound;toast(sound?'音效已开启':'音效已关闭');}if(e.code==='KeyF'){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>toast('当前窗口不支持全屏。'));}});window.addEventListener('keyup',e=>keys.delete(e.code));
canvas?.addEventListener('wheel',e=>{e.preventDefault();if(e.deltaY)changeSlot(()=>G.cycleSlot(state,e.deltaY));},{passive:false});
window.addEventListener('mousemove',e=>{if(!active||(document.pointerLockElement!==canvas&&e.target!==canvas))return;if(action){if(action.type==='airflow')G.adjustAirflow(state,e.movementX);return;}scene.look(e.movementX,e.movementY);});canvas?.addEventListener('contextmenu',e=>e.preventDefault());
function hitSword(hit){return hit?.target?.startsWith('item:')?G.swordOf(state,hit.target.slice(5)):null;}
function stationOf(hit){const c=hitSword(hit);return c&&(c.location==='anvil'||c.location.startsWith('display:'))?c.location:hit?.target;}
function beginInteraction(){const hit=scene.pick(),target=hit?.target,item=G.heldItem(state);if(!target)return;
 if(item?.kind==='hammer'&&stationOf(hit)==='anvil'){const result=perform(()=>G.strike(state,G.timingAccuracy(elapsed),elapsed));if(result){scene.hit(hit.point,result.broken);tone(result.broken?'break':'hit');}return;}
 if(G.carryingSword(state)){const station=stationOf(hit);if(['anvil','sale','scrap'].includes(station)||station?.startsWith('display:')){const result=perform(()=>G.putDown(state,station,scene.dropPoint(hit)));if(result)tone(station==='sale'?'sell':'pick');return;}if(target==='water'){if(!G.canQuench(state)){toast('至少成功锻打 3 锤后才能冷却。断剑请回收，成剑无需重复淬火。');return;}action={type:'quench'};return;}}
 if(target.startsWith('item:')){const id=target.slice(5),i=state.items.find(i=>i.id===id);const result=perform(()=>i?.kind==='crate'&&i.stored&&i.count>0&&!keys.has('ShiftLeft')&&!keys.has('ShiftRight')?G.takeOre(state,id):G.pickup(state,id));if(result!==null)tone('pick');return;}
 if(item){if(item.kind==='ore'&&target==='furnace'){perform(()=>G.putDown(state,'furnace',[]));tone('pick');return;}toast('滚轮切到空格，或右键放下当前物品，再操作此工位。');return;}
 if(target.startsWith('order:')){perform(()=>G.orderOre(state,target.slice(6)));tone('pick');return;}
 if(target.startsWith('mold:')){perform(()=>G.selectMold(state,target.slice(5)));tone('pick');return;}
 if(target==='lottery'){scene.lotteryPullUntil=scene.clock+1;toast('炉印抽奖机 · 奖池筹备中，当前不消耗炉印。');tone('pick');return;}
 if(target==='blower'){action={type:'airflow'};return;}
 if(target==='valve'){perform(()=>G.toggleValve(state));tone('pick');return;}
 if(target==='bed'){action={type:'sleep',progress:0};return;}
 toast({furnace:'从入库矿筐取矿，投入炉口；进气量设置后可离开处理其他工序。',mold:'铁水放出前仍可换模具。铸好的热剑坯必须用夹钳拿取。',anvil:'使用夹钳将剑坯放上铁砧，再用滚轮装备锻锤。',water:'用夹钳夹着已锻打至少 3 次的剑刃，按住左键浸水。',sale:'将冷却后的成剑放到台面出售，获得金币和炉印。',stock:'开局赠送一筐赤铁矿。左键逐块放入物品栏。',scrap:'在此回收断剑或空矿筐。',orders:'瞄准矿石样本，左键订购一筐，次日送达。'}[target]||(target.startsWith('display:')?'对准空挂架右键悬挂成剑，左键可取回。':''));
}
canvas?.addEventListener('mousedown',e=>{if(!active||action?.type==='transition')return;e.preventDefault();if(e.button===0)beginInteraction();if(e.button===2){action=null;const hit=scene.pick(),target=stationOf(hit),result=perform(()=>G.putDown(state,target,scene.dropPoint(hit)));if(result)tone(target==='sale'?'sell':'pick');}});window.addEventListener('mouseup',e=>{if(e.button===0&&action&&action.type!=='transition'){action=null;scene.sync(state);save();}});
function itemName(i){if(!i)return '空格';if(i.kind==='ore')return G.oreOf(i.ore).name;if(i.kind==='crate')return G.oreOf(i.ore).name+'矿筐 · '+i.count+'块';if(i.kind==='tongs')return G.atStation(state,'tongs')?'夹钳 · '+(G.hotSword(G.carriedSword(state))?'热剑坯':'成剑'):'夹钳';if(i.kind==='hammer')return '锻锤';const c=G.swordOf(state,i.id);return c?.stage==='broken'?'断裂废剑':c?.stage==='finished'?G.shapeOf(c.shape).name:'炽热剑坯';}
function hint(hit){const target=hit?.target,item=G.heldItem(state);if(!target)return ['','走近物体，瞄准后操作'];if(target.startsWith('item:')){const i=state.items.find(i=>i.id===target.slice(5)),c=hitSword(hit);if(c){if(item?.kind==='hammer'&&c.location==='anvil')return ['锻造剑坯','左键落锤 · 抓准金色中心'];if(G.hotSword(c))return ['炽热剑坯',item?.kind==='tongs'?'左键夹起 · 热剑不能收入物品栏':'需要先装备夹钳 · 热剑不能收纳'];}if(i?.kind==='crate')return [itemName(i),i.stored&&i.count?'左键取一块入栏 · Shift + 左键抱整筐':'左键搬整筐'+(i.count?'，运入工房':'，到废料箱回收')];return [itemName(i),'左键收入物品栏 · 滚轮切换'];}
 if(target.startsWith('order:')){const o=G.oreOf(target.slice(6));return [o.name+' · 订购',`左键订购 4 块 / ${o.cost*4} 金币 · 第 ${state.day+1} 天送达`];}if(target.startsWith('mold:')){const sh=G.shapeOf(target.slice(5));return [sh.name+'模具',`左键装入 · 用料 ${sh.cost} 块 · 铁水放出后锁定`];}
 if(target.startsWith('display:'))return ['墙面藏剑位 '+(Number(target.slice(8))+1),'右键竖挂冷却成剑 · 左键取回物品栏'];
 return {furnace:['熔炉',item?.kind==='ore'?'右键投入当前格矿石':`进气 ${Math.round(state.furnace.airflow)}% · ${G.temperatureTrend(state)}`],blower:['进气旋钮',item?'切换空格后操作旋钮':'按住左键左右拖动旋转 · 向右加大，向左减小'],valve:['出液口阀门',state.furnace.valve?'左键关闭 · 浇铸暂停':'左键打开 · 铁水自动流入模具'],mold:['浇铸模具',G.shapeOf(state.selectedShape).name+' · 铸成热剑坯用夹钳移走'],anvil:['锻造铁砧',G.carryingSword(state)?'右键放下剑坯':item?.kind==='hammer'?'左键按时机落锤':'使用夹钳将剑坯放到这里'],water:['冷却水槽',G.carryingSword(state)?'按住左键，将剑刃浸入水中':'至少锻打三锤，再用夹钳搬来冷却'],sale:['成剑售卖台',G.carryingSword(state)?`右键出售 · ${G.price(state)} 金币 + 1 炉印`:'放下冷却后的成剑，换取金币与炉印'],stock:['矿石存放区','左键取矿入栏 · 整筐货物需亲手搬入工房'],bed:['休息床铺',item?'切到空格再休息':'按住左键 2 秒休息 · 王令期限照常推进'],scrap:['废料回收箱','右键放入断剑或空矿筐'],orders:['订矿桌','瞄准矿石样本查看价格'],lottery:['炉印抽奖机','左键拉动摇杆 · 奖池筹备中，不消耗炉印']}[target]||['',''];
}
function renderInventory(){const occupied=state.inventory.filter(Boolean).length;$('#inventory-caption').textContent=G.hotSword(G.carriedSword(state))?'热剑坯夹持中 · 放下后才能切换':G.heldItem(state)?.kind==='crate'?'抱筐搬运中 · 右键放下':'物品栏 '+occupied+'/5 · 滚轮 / 1–5 切换';$('#inventory-slots').innerHTML=state.inventory.map((id,n)=>{const i=state.items.find(i=>i.id===id),c=i?.kind==='sword'?G.swordOf(state,id):null;const icon=!i?'·':i.kind==='hammer'?'⚒':i.kind==='tongs'?'⋈':i.kind==='ore'?'◆':'†',color=i?.kind==='ore'?G.oreOf(i.ore).color:c?G.alloyOf(c).color:'#e7c78b';return '<div class="inventory-slot '+(state.selectedSlot===n?'selected':'')+'"><small>'+(n+1)+'</small><span style="color:'+color+'">'+icon+'</span><b>'+itemName(i)+'</b></div>';}).join('');}
function renderHUD(){const [step,title,detail]=G.objective(state);$('#money').textContent=Math.round(state.money).toLocaleString('zh-CN');$('#tokens').textContent=state.tokens;$('#sold').innerHTML=state.sold+' <em>把</em>';const minute=480+Math.floor(state.dayTime/G.DAY_LENGTH*720);$('#day-label').textContent=`第 ${state.day} 天 · ${String(Math.floor(minute/60)).padStart(2,'0')}:${String(minute%60).padStart(2,'0')}`;$('#objective').textContent=title;$('#objective-detail').textContent=detail;document.querySelectorAll('[data-step]').forEach(e=>{const n=Number(e.dataset.step);e.classList.toggle('active',n===step);e.classList.toggle('done',n<step);});$('#held-name').textContent=state.held?itemName(G.heldItem(state)):'双手空闲';$('#orders-info').textContent=state.orders.length?`在途 ${state.orders.length} 筐`:'在坊剑刃 '+state.swords.length+' 把';renderInventory();
 const king=state.king,fulfilled=king.status==='fulfilled',nextDay=Math.floor(king.deadline/G.DAY_LENGTH)+1;$('#king-title').textContent=king.title+(fulfilled?' · 已完成':'');$('#king-time-prefix').textContent=fulfilled?'下期':'剩余';$('#king-time').textContent=fulfilled?'第 '+nextDay+' 天发布下一单':G.deadlineText(state);$('#king-progress').textContent=king.delivered+' / '+king.quantity;$('#king-requirements').textContent=G.requirements(king);$('#royal-order').classList.toggle('urgent',!fulfilled&&king.deadline-G.gameTime(state)<G.DAY_LENGTH);$('#royal-order').classList.toggle('fulfilled',fulfilled);$('#king-deadline').textContent=fulfilled?'本期已完成 · 成剑可自由出售或展示':'第 '+king.issuedDay+'–'+(nextDay-1)+' 天 · 冷却成剑自动核验 · 逾期失败';
 const hit=scene.pick(),[name,help]=hint(hit);$('#target-name').textContent=name;$('#target-action').textContent=action?{airflow:'左减 / 右增 · 中位保温，开大升温，关小降温',quench:'剑刃浸水中 · 保持左键按下',sleep:'正在休息 · 保持左键按下',transition:'夜尽，炉火再起'}[action.type]:help;$('#crosshair').classList.toggle('hot',!!hit?.target);
 let progress=null,info='';const f=state.furnace,o=G.alloyOf(f),held=G.heldItem(state),heldSword=G.carriedSword(state);if(action?.type==='airflow'){progress=f.airflow;info='进气 '+Math.round(f.airflow)+'% · '+G.temperatureTrend(state);}if(action?.type==='quench'){progress=heldSword?.quench;info='冷却 '+Math.round(progress)+'%';}if(action?.type==='sleep'){progress=action.progress/2*100;info='休息到第 '+(state.day+1)+' 天 · 期限照常推进';}$('#action-meter').hidden=progress===null;$('#action-meter i').style.width=(progress||0)+'%';$('#action-info').textContent=info;
 const anvil=G.atStation(state,'anvil'),c=hitSword(hit)||heldSword||(held?.kind==='hammer'?anvil:null)||anvil||G.atStation(state,'mold'),forging=anvil&&held?.kind==='hammer'&&!['finished','broken'].includes(anvil.stage);$('#timing').hidden=!forging;$('#risk-value').textContent=(G.risk(state)*100).toFixed(1)+'%';$('#risk-value').classList.toggle('danger',G.risk(state)>.1);$('#hit-count').textContent=(anvil?.hits||0)+' 锤';
 const target=hit?.target,panel=$('#work-info');panel.hidden=false;
 if(target==='lottery'){panel.innerHTML='<div class="eyebrow">COMING SOON / 炉印抽奖</div><strong>奖池筹备中</strong><p>已存炉印 <b class="token-color">'+state.tokens+'</b> 枚</p><small>出售每把成剑获得 1 枚炉印。完成国王订单另有赏金与炉印。<br>抽奖规则后续开放，当前不消耗货币。</small>';
 }else if(target?.startsWith('order:')){const ore=G.oreOf(target.slice(6));panel.innerHTML='矿石订购<strong>'+ore.name+'</strong>熔点 '+ore.melt+'°C<br>基础锋利 '+ore.sharp+' · 硬度 '+ore.hard+'<br>基础韧性 '+ore.tough+' · 密度 '+ore.density+'<br><div class="appraisal">一筐 / 4 块 <b>'+ore.cost*4+'</b> 金币</div><small>'+ore.desc+'<br>次日送货，整筐搬入工房后取用。</small>';
 }else if(target?.startsWith('mold:')){const sh=G.shapeOf(target.slice(5));panel.innerHTML='模具选择<strong>'+sh.name+'</strong>耗料 '+sh.cost+' 块 · 基础重量 '+sh.weight+' kg<br>锋利 ×'+sh.sharp+' · 硬度 ×'+sh.hard+'<br>韧性 ×'+sh.tough+'<br><small>铁水放出前可随时换模具，剩余金属保留。<br>当前：'+G.shapeOf(state.selectedShape).name+'</small>';
 }else if(action?.type==='airflow'||['furnace','blower','valve','mold'].includes(target)||(o&&!c)){panel.innerHTML=(o?o.name:'熔炉预热')+'<strong>'+Math.round(f.temp)+' <small>°C</small></strong><div class="furnace-track"><i style="width:'+f.airflow+'%"></i></div><b>进气 '+Math.round(f.airflow)+'%</b><br>'+G.temperatureTrend(state)+'<br><small>'+(o?`理想温区 ${o.melt}–${o.melt+100}°C`:'50% 保温，开大升温，关小降温')+'</small><br>炉内 '+f.loaded+' 块 · 模具需 '+G.shapeOf(state.selectedShape).cost+' 块<br>'+(o?'<small>'+G.compositionText(f)+'<br>配料基础：锋 '+Number(o.sharp.toFixed(1))+' · 硬 '+Number(o.hard.toFixed(1))+' · 韧 '+Number(o.tough.toFixed(1))+'<br>密度 '+o.density.toFixed(2)+'</small><br>':'')+'熔化 '+Math.floor(f.progress)+'% · 铸型 '+Math.floor(state.mold.fill)+'%<br><small>松手后进气保持不变 · 50% 保温。</small>';
 }else if(c){const a=G.attributes(c);panel.innerHTML='<div class="eyebrow">'+G.alloyOf(c).name+' / '+G.shapeOf(c.shape).name+'</div><strong>'+(c.stage==='broken'?'报废':G.qualityName(G.qualityScore(c)))+' <small>'+G.qualityScore(c).toFixed(1)+' 分</small></strong><div class="sword-stats">'+[['锋利度',a.sharp],['硬度',a.hard],['韧性',a.tough],['重量',a.weight+' kg']].map(([k,v])=>'<div><span>'+k+'</span><b>'+v+'</b></div>').join('')+'</div><small>'+G.compositionText(c)+'</small><div class="stat-summary">锻打 '+c.hits+' 次 · '+({blank:'热剑坯',forged:'可继续锻打 / 淬火',finished:'成剑',broken:'已报废'}[c.stage])+'</div><div class="appraisal">估价 <b>'+G.price(state,c)+'</b> 金币 + 1 炉印</div><small>'+(c.creditedKing?'已计入第 '+c.creditedKing+' 道王令，成剑仍归你所有。':G.hotSword(c)?'热剑不可收纳，夹钳搬运到工位。冷却后可入栏。':'冷却成剑自动核验国王任务，无需交付。')+'</small>';
 }else{panel.innerHTML='当前模具<strong>'+G.shapeOf(state.selectedShape).name+'</strong>需要 '+G.shapeOf(state.selectedShape).cost+' 块矿石，可混合配料<br><small>五格物品栏：工具、矿石、冷却成剑。<br>热剑必须夹钳搬运，不能收纳。<br>左侧无窗墙上有三个藏剑挂架。</small>';}
}
function startSleep(){action={type:'transition',progress:0,advanced:false};keys.clear();$('#sleep-screen').classList.remove('dawn');$('#sleep-screen').hidden=false;$('#sleep-title').textContent='炉火渐息';$('#sleep-subtitle').textContent='山间工坊入夜';$('#sleep-screen').style.opacity='0';}
function sleepFrame(dt){const a=action;a.progress+=dt;const p=a.progress;$('#sleep-screen').style.opacity=String(Math.min(1,p/.7,(4.5-p)/.8));$('#sleep-screen').classList.toggle('dawn',p>=2.1);if(p>=1.6&&!a.advanced){a.advanced=true;const msg=G.nextDay(state);save();toast(msg);if(state.gameOver){checkFailure();return;}$('#sleep-title').textContent='第 '+state.day+' 天';$('#sleep-subtitle').textContent='晨光已至 · '+(state.items.filter(i=>i.kind==='crate'&&!i.stored).length?'新货在庭院等你':'新的炉火，新的锋刃');scene.sync(state);}if(p>=4.5){action=null;$('#sleep-screen').hidden=true;tone('pick');}}
function frame(now){const dt=Math.max(0,Math.min((now-last)/1000,.05));last=now;let moving=false;if(active&&!document.hidden){elapsed+=dt;if(action?.type==='transition')sleepFrame(dt);else{if(!action){const f=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0),r=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),len=Math.hypot(f,r)||1,heavy=G.heldItem(state)?.kind==='crate',speed=(heavy?2.15:keys.has('ShiftLeft')?5.6:3.6)*dt,p=state.player;scene.move((-Math.sin(p.yaw)*f+Math.cos(p.yaw)*r)/len*speed,(-Math.cos(p.yaw)*f-Math.sin(p.yaw)*r)/len*speed);moving=!!(f||r);scene.look(((keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0))*dt*650,((keys.has('ArrowDown')?1:0)-(keys.has('ArrowUp')?1:0))*dt*500);}if(action?.type==='sleep'){action.progress+=dt;if(action.progress>=2)startSleep();}if(action?.type!=='transition'){const msg=G.tick(state,dt,action);if(msg){toast(msg);if(action?.type==='quench'&&G.carriedSword(state)?.stage==='finished')action=null;save();tone('pick');}checkFailure();}}scene.sync(state);saveClock+=dt;if(saveClock>2){save();saveClock=0;}}
 if(scene){scene.update(active?dt:0,{action,moving});$('#timing-pointer').style.left=G.timingPosition(elapsed)*100+'%';hudClock+=dt;if(hudClock>.08){renderHUD();hudClock=0;}}requestAnimationFrame(frame);}
if(scene){renderHUD();checkFailure();requestAnimationFrame(frame);}Object.defineProperty(window,'workshopSnapshot',{value:()=>structuredClone({state,active,action,elapsed,target:scene?.pick()?.target,scene:{colliders:scene?.colliders.length}}),writable:false});
